                 //                     "filled_amount": "0.2",
                 //                     "type": "STOP",
                 //                     "sequence": 8,
                 //                     "status": "FILLED_FULLY"
                 //                 },
                 //                 "trades": [
                 //                     {
                 //                         "fee": {
                 //                             "fee_amount": "0.4188869",
                 //                             "fee_currency": "USDT",
                 //                             "fee_percentage": "0.1",
                 //                             "fee_group_id": "default",
                 //                             "fee_type": "TAKER",
                 //                             "running_trading_volume": "0.0"
                 //                         },
                 //                         "trade": {
                 //                             "trade_id":
                 //                             "ec82896f-fd1b-4cbb-89df-a9da85ccbb4b",
                 //                             "order_id":
                 //                             "d453ca12-c650-46dd-9dee-66910d96bfc0",
                 //                             "account_id":
                 //                             "ef3a5f4c-cfcd-415e-ba89-5a9abf47b28a",
                 //                             "amount": "0.2",
